local PresentationAxeMaker = {}
local PRODUCTS = {
    simple_iron_presentation_axe = { name = "Preprost železni predstavitvena sekira", ironCost = 3, woodCost = 2, time = 5, cost = 180, prestige = 5, happiness = 2, description = "Preprost železni predstavitvena sekira za parade." },
    silver_blade_presentation_axe = { name = "Srebrnorezna predstavitvena sekira", silverCost = 2, ironCost = 2, woodCost = 2, time = 8, cost = 440, prestige = 12, happiness = 3, description = "Srebrnorezna predstavitvena sekira za trgovce." },
    gold_trimmed_presentation_axe = { name = "Zlatookrasna predstavitvena sekira", goldCost = 1, silverCost = 1, ironCost = 2, woodCost = 2, time = 12, cost = 1000, prestige = 22, happiness = 4, description = "Zlatookrasna predstavitvena sekira za plemiče." },
    jewel_set_presentation_axe = { name = "Draguljasta predstavitvena sekira", goldCost = 2, silverCost = 1, ironCost = 2, woodCost = 2, jewelCost = 1, time = 16, cost = 2300, prestige = 35, happiness = 6, description = "Predstavitvena sekira z draguljem za visoke plemiče." },
    pearl_set_presentation_axe = { name = "Bisernavi predstavitvena sekira", goldCost = 2, silverCost = 1, ironCost = 2, woodCost = 2, jewelCost = 1, pearlCost = 1, time = 20, cost = 4800, prestige = 50, happiness = 8, description = "Predstavitvena sekira z biseri za visoko plemstvo." },
    royal_grand_presentation_axe = { name = "Kraljevski veliki predstavitvena sekira", goldCost = 3, silverCost = 2, ironCost = 2, woodCost = 2, jewelCost = 2, pearlCost = 2, time = 27, cost = 10000, prestige = 72, happiness = 13, description = "Velika kraljevska predstavitvena sekira z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    presentation_workshop = { name = "Predstavitvena delavnica", cost = { gold = 300, wood = 140, stone = 120, iron = 6 }, upkeep = 7, qualityBonus = 5 },
    armorer_loft = { name = "Okleparska podstrešje", cost = { gold = 1100, wood = 280, stone = 280, silver = 6, gold = 4 }, upkeep = 26, qualityBonus = 18 },
    master_axe_atelier = { name = "Mojstrski sekiarski atelje", cost = { gold = 2800, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_armory_palace = { name = "Kraljevska orožarnaica palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
PresentationAxeMaker.ironStock = 16; PresentationAxeMaker.woodStock = 14; PresentationAxeMaker.silverStock = 8; PresentationAxeMaker.goldStock = 6; PresentationAxeMaker.jewelStock = 4; PresentationAxeMaker.pearlStock = 4
PresentationAxeMaker.productStock = {}; PresentationAxeMaker.buildings = {}; PresentationAxeMaker.maker = nil; PresentationAxeMaker.activeMaking = {}; PresentationAxeMaker.totalProducts = 0; PresentationAxeMaker.dayTimer = 0
function PresentationAxeMaker.init() PresentationAxeMaker.ironStock=16; PresentationAxeMaker.woodStock=14; PresentationAxeMaker.silverStock=8; PresentationAxeMaker.goldStock=6; PresentationAxeMaker.jewelStock=4; PresentationAxeMaker.pearlStock=4; PresentationAxeMaker.productStock={}; PresentationAxeMaker.buildings={}; PresentationAxeMaker.maker=nil; PresentationAxeMaker.activeMaking={}; PresentationAxeMaker.totalProducts=0; PresentationAxeMaker.dayTimer=0; print("[PresentationAxeMaker] Royal Presentation Axe Maker System initialized (6 products, 4 buildings)") end
function PresentationAxeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PresentationAxeMaker.maker={name=n or ("Predstavitveni sekiar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Predstavitveni sekiar najet: %s (spretnost: %d)",PresentationAxeMaker.maker.name,s),"success") end; return true end
function PresentationAxeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PresentationAxeMaker.build(id) local ok,e=PresentationAxeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PresentationAxeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PresentationAxeMaker.getQualityBonus() local b=0; for _,bd in ipairs(PresentationAxeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PresentationAxeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PresentationAxeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.woodCost and PresentationAxeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and PresentationAxeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PresentationAxeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PresentationAxeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PresentationAxeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PresentationAxeMaker.buildings==0 then return false,"Potrebna predstavitvena delavnica" end; if not PresentationAxeMaker.maker then return false,"Potreben predstavitveni sekiar" end; return true end
function PresentationAxeMaker.make(pt,qty) qty=qty or 1; local ok,e=PresentationAxeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PresentationAxeMaker.ironStock=PresentationAxeMaker.ironStock-d.ironCost*qty end; if d.woodCost then PresentationAxeMaker.woodStock=PresentationAxeMaker.woodStock-d.woodCost*qty end; if d.silverCost then PresentationAxeMaker.silverStock=PresentationAxeMaker.silverStock-d.silverCost*qty end; if d.goldCost then PresentationAxeMaker.goldStock=PresentationAxeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PresentationAxeMaker.jewelStock=PresentationAxeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PresentationAxeMaker.pearlStock=PresentationAxeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PresentationAxeMaker.maker then t=math.max(1,t-math.floor(PresentationAxeMaker.maker.skill/12)) end; table.insert(PresentationAxeMaker.activeMaking,{id="presentationaxe_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kovanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PresentationAxeMaker.completeMaking(m) local q=1.0+(PresentationAxeMaker.getQualityBonus()/100); if PresentationAxeMaker.maker then q=q+(PresentationAxeMaker.maker.skill/140) end; q=math.min(2.5,q); PresentationAxeMaker.productStock[m.productType]=(PresentationAxeMaker.productStock[m.productType] or 0)+m.quantity; PresentationAxeMaker.totalProducts=PresentationAxeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PresentationAxeMaker.maker then PresentationAxeMaker.maker.itemsMade=PresentationAxeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PresentationAxeMaker.maker.skill=math.min(100,PresentationAxeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Predstavitvena sekira izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"presentationaxe.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PresentationAxeMaker.update(dt) if not _G.state then return end; PresentationAxeMaker.dayTimer=PresentationAxeMaker.dayTimer+dt; if PresentationAxeMaker.dayTimer>=30 then PresentationAxeMaker.dayTimer=0; for i=#PresentationAxeMaker.activeMaking,1,-1 do local m=PresentationAxeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PresentationAxeMaker.completeMaking(m); table.remove(PresentationAxeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PresentationAxeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PresentationAxeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PresentationAxeMaker.getStats() return {ironStock=PresentationAxeMaker.ironStock,woodStock=PresentationAxeMaker.woodStock,silverStock=PresentationAxeMaker.silverStock,goldStock=PresentationAxeMaker.goldStock,jewelStock=PresentationAxeMaker.jewelStock,pearlStock=PresentationAxeMaker.pearlStock,productStock=PresentationAxeMaker.productStock,numBuildings=#PresentationAxeMaker.buildings,hasMaker=PresentationAxeMaker.maker~=nil,makerName=PresentationAxeMaker.maker and PresentationAxeMaker.maker.name or "—",makerSkill=PresentationAxeMaker.maker and PresentationAxeMaker.maker.skill or 0,activeMaking=#PresentationAxeMaker.activeMaking,totalProducts=PresentationAxeMaker.totalProducts} end
return PresentationAxeMaker
